# Data files generated by src.data_collector / src.feature_engineering
DEFAULT_DATA_PREFIX = "f1_data"

# Enable FastF1 cache
fastf1.Cache.enable_cache(str(FASTF1_CACHE_DIR))


def resolve_data_file(prefix: str, key: str) -> Path:
    """
    Resolve a data file path using the selected prefix, with legacy fallback.
    """
    preferred = DATA_DIR / f"{prefix}_{key}.csv"
    if preferred.exists():
        return preferred

    legacy = DATA_DIR / f"f1_data_2023_{key}.csv"
    if legacy.exists():
        logger.warning(f"Using legacy data file {legacy.name}; regenerate with prefix '{prefix}' for latest data.")
        return legacy

    return preferred


def resolve_cli_year(year_arg: str, parser: argparse.ArgumentParser) -> int:
    """
    Resolve CLI year argument.

    Supports numeric years and dynamic aliases: auto/current/today.
    """
    normalized = str(year_arg).strip().lower()
    if normalized in {'auto', 'current', 'today'}:
        return pd.Timestamp.now().year
    if normalized.isdigit():
        return int(normalized)

    parser.error(f"Invalid value for --year: '{year_arg}'. Use a 4-digit year or 'auto'.")
    return pd.Timestamp.now().year


def get_current_standings(year: int) -> pd.DataFrame:
    """
    Get live driver and constructor standings as of today.
    Calculated from completed race results in the selected season.
    """
    from .data_collector import get_event_schedule, get_race_results

    schedule = get_event_schedule(year)
    if schedule.empty:
        logger.warning(f"No race schedule available for {year}")
        return pd.DataFrame()

    completed_rounds = schedule[schedule['EventDate'] < pd.Timestamp.now()]['RoundNumber'].tolist()

    if not completed_rounds:
        logger.warning(f"No completed races in {year}")
        return pd.DataFrame()

    # Collect all race results
    races = []
    for round_num in completed_rounds:
        result = get_race_results(year, round_num)
        if not result.empty:
            races.append(result)

    if not races:
        return pd.DataFrame()

    all_races = pd.concat(races, ignore_index=True)

    # Use official points from race results when available.
    if 'Points' in all_races.columns:
        all_races['RacePoints'] = pd.to_numeric(all_races['Points'], errors='coerce').fillna(0)
    else:
        points_map = {
            1: 25, 2: 18, 3: 15, 4: 12, 5: 10,
            6: 8, 7: 6, 8: 4, 9: 2, 10: 1
        }
        all_races['Position'] = pd.to_numeric(all_races['Position'], errors='coerce')
        all_races['RacePoints'] = all_races['Position'].map(points_map).fillna(0)

    # Driver standings (as of latest completed race)
    driver_points = all_races.groupby('Abbreviation', as_index=False)['RacePoints'].sum()
    driver_points = driver_points.rename(columns={
        'Abbreviation': 'Driver',
        'RacePoints': 'DriverPointsBefore'
    })
    driver_points['DriverChampionshipPosition'] = driver_points['DriverPointsBefore'].rank(
        ascending=False,
        method='min'
    )

    # Team mapping and constructor standings
    driver_team = all_races[['Abbreviation', 'TeamName']].dropna().drop_duplicates(subset=['Abbreviation'], keep='last')
    driver_team = driver_team.rename(columns={'Abbreviation': 'Driver'})
    driver_points = driver_points.merge(driver_team, on='Driver', how='left')

    constructor_points = all_races.groupby('TeamName', as_index=False)['RacePoints'].sum()
    constructor_points = constructor_points.rename(columns={'RacePoints': 'ConstructorPointsBefore'})
    constructor_points['ConstructorChampionshipPosition'] = constructor_points['ConstructorPointsBefore'].rank(
        ascending=False,
        method='min'
    )

    standings = driver_points.merge(
        constructor_points[['TeamName', 'ConstructorPointsBefore', 'ConstructorChampionshipPosition']],
        on='TeamName',
        how='left'
    )
    standings['Year'] = year
    standings['Round'] = max(completed_rounds)

    return standings.sort_values('DriverChampionshipPosition').reset_index(drop=True)


def display_current_standings(year: int):
    """Display live championship standings based on completed races up to today."""
    standings = get_current_standings(year)
    if standings.empty:
        print(f"No standings available yet for {year}.")
        return None

    latest_round = int(standings['Round'].max())
    today = pd.Timestamp.now().strftime('%Y-%m-%d')

    print("\n" + "=" * 84)
    print(f"[F1] CURRENT DRIVER STANDINGS ({year}) - AS OF {today} (AFTER ROUND {latest_round})")
    print("=" * 84)
    print(f"{'Pos':<5}{'Driver':<10}{'Team':<25}{'Pts':<8}{'Const Pos':<10}{'Const Pts':<10}")
    print("-" * 84)

    display_df = standings.sort_values('DriverChampionshipPosition')
    for _, row in display_df.iterrows():
        print(
            f"{int(row['DriverChampionshipPosition']):<5}"
            f"{row['Driver']:<10}"
            f"{str(row['TeamName'])[:24]:<25}"
            f"{float(row['DriverPointsBefore']):<8.1f}"
            f"{int(row['ConstructorChampionshipPosition']):<10}"
            f"{float(row['ConstructorPointsBefore']):<10.1f}"
        )

    print("=" * 84)
    return standings


def get_qualifying_grid(year: int, round_number: int) -> pd.DataFrame:
    """
    Get qualifying results / starting grid for a specific race.
    """
    try:
        session = fastf1.get_session(year, round_number, 'Q')
        session.load(telemetry=False, weather=False, messages=False)

        results = session.results.copy()
        results['GridPosition'] = pd.to_numeric(results['Position'], errors='coerce')
        results['Driver'] = results['Abbreviation']
        results['Team'] = results['TeamName']

        return results[['Driver', 'Team', 'GridPosition', 'FullName']]

    except Exception as e:
        logger.warning(f"Could not load qualifying data: {e}")
        return pd.DataFrame()


def calculate_driver_track_history(driver: str, circuit: str, races_df: pd.DataFrame) -> float:
    """Calculate a driver's average position at a specific circuit."""
    if races_df.empty:
        return np.nan

    driver_races = races_df[
        (races_df['Abbreviation'] == driver) &
        (races_df['EventName'].str.contains(circuit, case=False, na=False))
    ]

    if len(driver_races) > 0:
        return driver_races['Position'].mean()
    return np.nan


def calculate_recent_form(driver: str, races_df: pd.DataFrame, n_races: int = 3) -> float:
    """Calculate driver's average position in last N races."""
    if races_df.empty:
        return np.nan

    driver_races = races_df[races_df['Abbreviation'] == driver].tail(n_races)

    if len(driver_races) > 0:
        return driver_races['Position'].mean()
    return np.nan


def prepare_prediction_features(year: int, round_number: int, data_prefix: str = DEFAULT_DATA_PREFIX) -> pd.DataFrame:
    """
    Prepare features for predicting an upcoming race.
    """
    # Get qualifying grid
    grid = get_qualifying_grid(year, round_number)
    if grid.empty:
        logger.error("No qualifying data available")
        return pd.DataFrame()

    # Get current standings
    standings = get_current_standings(year)

    # Get historical race data
    historical_path = resolve_data_file(data_prefix, "races")
    historical_races = pd.DataFrame()
    if historical_path.exists():
        historical_races = pd.read_csv(historical_path)

    # Build feature dataframe
    features = []

    for _, row in grid.iterrows():
        driver = row['Driver']
        team = row['Team']
        grid_pos = row['GridPosition']

        # Get standings info
        driver_standing = standings[standings['Driver'] == driver]

        if len(driver_standing) > 0:
            driver_champ_pos = driver_standing['DriverChampionshipPosition'].values[0]
            driver_points = driver_standing['DriverPointsBefore'].values[0]
            constructor_champ_pos = driver_standing['ConstructorChampionshipPosition'].values[0]
            constructor_points = driver_standing['ConstructorPointsBefore'].values[0]
        else:
            driver_champ_pos = 20
            driver_points = 0
            constructor_champ_pos = 10
            constructor_points = 0

        # Track history and recent form
        track_history = calculate_driver_track_history(driver, "", historical_races)
        recent_form = calculate_recent_form(driver, historical_races)

        features.append({
            'Driver': driver,
            'FullName': row['FullName'],
            'Team': team,
            'GridPosition': grid_pos if pd.notna(grid_pos) else 20,
            'DriverChampPosition': driver_champ_pos,
            'DriverPoints': driver_points,
            'ConstructorChampPosition': constructor_champ_pos,
            'ConstructorPoints': constructor_points,
            'TrackHistoryAvgPos': track_history if pd.notna(track_history) else grid_pos,
            'RecentForm': recent_form if pd.notna(recent_form) else grid_pos,
            'QualifyingGap': 5.0  # Default value
        })

    return pd.DataFrame(features)


def predict_race(
    year: int,
    round_number: int,
    model_name: str = "best_model",
    data_prefix: str = DEFAULT_DATA_PREFIX
) -> pd.DataFrame:
    """
    Predict race results for a given race.

    Args:
        year: Season year
        round_number: Race round number
        model_name: Name of saved model to use

    Returns:
        DataFrame with predicted finishing positions
    """
    # Load model
    model = load_model(model_name)

    # Prepare features
    features_df = prepare_prediction_features(year, round_number, data_prefix)
    if features_df.empty:
        logger.error("Could not prepare features")
        return pd.DataFrame()

    # Get feature columns for prediction
    feature_cols = get_feature_columns()
    X = features_df[feature_cols]

    # Make predictions
    predictions = predict_positions(model, X)

    # Create results dataframe
    results = features_df[['Driver', 'FullName', 'Team', 'GridPosition']].copy()
    results['PredictedPosition'] = predictions

    # Sort by predicted position
    results = results.sort_values('PredictedPosition').reset_index(drop=True)

    # Add position rank (handle ties)
    results['PredictedRank'] = range(1, len(results) + 1)

    return results


def display_predictions(results: pd.DataFrame, event_name: str = "Race"):
    """Display predictions in a formatted table."""
    print("\n" + "=" * 70)
    print(f"[F1] RACE PREDICTION: {event_name}")
    print("=" * 70)
    print(f"{'Pos':<5}{'Driver':<25}{'Team':<25}{'Grid':<8}")
    print("-" * 70)

    for idx, row in results.iterrows():
        pos = row['PredictedRank']
        driver = row['FullName'][:24]
        team = row['Team'][:24]
        grid = int(row['GridPosition']) if pd.notna(row['GridPosition']) else '-'

        # Podium indicators
        if pos == 1:
            pos_str = f"P1 *"
        elif pos == 2:
            pos_str = f"P2 *"
        elif pos == 3:
            pos_str = f"P3 *"
        else:
            pos_str = f"P{pos}"

        print(f"{pos_str:<5}{driver:<25}{team:<25}{grid:<8}")

    print("=" * 70)


def predict_from_historical(
    year: int,
    round_number: int,
    data_prefix: str = DEFAULT_DATA_PREFIX
) -> pd.DataFrame:
    """
    Make predictions using historical data (for testing).
    Uses already collected qualifying data.
    """
    model = load_model("best_model")

    # Load features file
    features_path = resolve_data_file(data_prefix, "features")
    if not features_path.exists():
        raise FileNotFoundError(
            f"Features file not found: {features_path.name}. Run feature engineering first."
        )

    all_features = pd.read_csv(features_path)

    # Filter for specific race
    race_features = all_features[
        (all_features['Year'] == year) &
        (all_features['Round'] == round_number)
    ].copy()

    if race_features.empty:
        raise ValueError(f"No data found for {year} Round {round_number}")

    # Make predictions
    feature_cols = get_feature_columns()
    X = race_features[feature_cols]
    predictions = predict_positions(model, X)

    # Create results
    results = race_features[['Driver', 'Team', 'GridPosition']].copy()
    results['PredictedPosition'] = predictions
    results['ActualPosition'] = race_features['FinishingPosition']
    results = results.sort_values('PredictedPosition').reset_index(drop=True)
    results['PredictedRank'] = range(1, len(results) + 1)

    return results


def compare_predictions(results: pd.DataFrame, event_name: str = "Race"):
    """Compare predictions vs actual results."""
    print("\n" + "=" * 80)
    print(f"[F1] PREDICTION vs ACTUAL: {event_name}")
    print("=" * 80)
    print(f"{'Driver':<10}{'Predicted':<12}{'Actual':<10}{'Diff':<10}{'Result'}")
    print("-" * 80)

    correct = 0
    within_3 = 0

    for idx, row in results.iterrows():
        driver = row['Driver']
        pred = int(row['PredictedPosition'])
        actual = int(row['ActualPosition'])
        diff = pred - actual

        if diff == 0:
            result = "[OK] EXACT"
            correct += 1
            within_3 += 1
        elif abs(diff) <= 3:
            result = "[~] Close"
            within_3 += 1
        else:
            result = "[X] Miss"

        diff_str = f"+{diff}" if diff > 0 else str(diff)
        print(f"{driver:<10}P{pred:<11}P{actual:<9}{diff_str:<10}{result}")

    print("-" * 80)
    print(f"Exact predictions: {correct}/{len(results)} ({100*correct/len(results):.1f}%)")
    print(f"Within 3 positions: {within_3}/{len(results)} ({100*within_3/len(results):.1f}%)")
    print("=" * 80)


def get_next_race_info(year: int = None):
    """
    Get information about the next upcoming race.

    Returns:
        tuple: (year, round_number, event_name, event_date, qualifying_available)
    """
    from .data_collector import get_event_schedule

    if year is None:
        year = pd.Timestamp.now().year

    schedule = get_event_schedule(year)
    if schedule.empty:
        return None

    # Find next race (event date >= today)
    now = pd.Timestamp.now()
    upcoming = schedule[schedule['EventDate'] >= now.normalize()]

    if upcoming.empty:
        # Try next year
        year += 1
        schedule = get_event_schedule(year)
        upcoming = schedule[schedule['EventDate'] >= now.normalize()]
        if upcoming.empty:
            return None

    next_race = upcoming.iloc[0]
    round_number = int(next_race['RoundNumber'])
    event_name = next_race['EventName']
    event_date = next_race['EventDate']

    # Check if qualifying has happened (usually Saturday before race)
    quali_date = event_date - pd.Timedelta(days=1)
    qualifying_available = now >= quali_date

    return {
        'year': year,
        'round': round_number,
        'event_name': event_name,
        'event_date': event_date,
        'qualifying_available': qualifying_available
    }


def resolve_race_query(race_query: str, default_year: int) -> dict:
    """
    Resolve a race query string to season year, round number, and event name.

    Supported query formats:
    - "Abu Dhabi Grand Prix"
    - "Abu Dhabi Grand Prix 2024"
    """
    from .data_collector import get_event_schedule

    query = race_query.strip()
    year = default_year

    year_match = re.search(r'(\d{4})\s*$', query)
    if year_match:
        year = int(year_match.group(1))
        query = query[:year_match.start()].strip()

    if not query:
        raise ValueError("Race name cannot be empty.")

    schedule = get_event_schedule(year)
    if schedule.empty:
        raise ValueError(f"Could not load race schedule for {year}.")

    event_names = schedule['EventName'].fillna("").astype(str)
    exact_match = schedule[event_names.str.casefold() == query.casefold()]
    if not exact_match.empty:
        race = exact_match.iloc[0]
        return {
            'year': year,
            'round': int(race['RoundNumber']),
            'event_name': race['EventName']
        }

    partial_match = schedule[event_names.str.contains(query, case=False, regex=False)]
    if len(partial_match) == 1:
        race = partial_match.iloc[0]
        return {
            'year': year,
            'round': int(race['RoundNumber']),
            'event_name': race['EventName']
        }

    if len(partial_match) > 1:
        matches = ", ".join(partial_match['EventName'].astype(str).tolist())
        raise ValueError(f"Race name is ambiguous. Matches: {matches}")

    raise ValueError(f"No race named '{query}' found in {year} schedule.")


def build_prediction_from_standings(year: int, model_name: str = "best_model") -> pd.DataFrame:
    """Build prediction dataframe using championship standings as an estimated grid."""
    model = load_model(model_name)

    standings = get_current_standings(year)
    if standings.empty:
        standings = get_current_standings(year - 1)

    if standings.empty:
        return pd.DataFrame()

    standings = standings.sort_values('DriverChampionshipPosition')

    features = []
    for grid_pos, (_, row) in enumerate(standings.iterrows(), 1):
        features.append({
            'Driver': row['Driver'],
            'FullName': row['Driver'],
            'Team': row['TeamName'],
            'GridPosition': grid_pos,
            'DriverChampPosition': row['DriverChampionshipPosition'],
            'DriverPoints': row['DriverPointsBefore'],
            'ConstructorChampPosition': row['ConstructorChampionshipPosition'],
            'ConstructorPoints': row['ConstructorPointsBefore'],
            'TrackHistoryAvgPos': grid_pos,
            'RecentForm': grid_pos,
            'QualifyingGap': 5.0
        })

    features_df = pd.DataFrame(features)
    feature_cols = get_feature_columns()
    X = features_df[feature_cols]
    predictions = predict_positions(model, X)

    results = features_df[['Driver', 'FullName', 'Team', 'GridPosition']].copy()
    results['PredictedPosition'] = predictions
    results = results.sort_values('PredictedPosition').reset_index(drop=True)
    results['PredictedRank'] = range(1, len(results) + 1)
    return results


def predict_next_race(
    model_name: str = "best_model",
    data_prefix: str = DEFAULT_DATA_PREFIX,
    year: int = None,
    mode: str = "auto"
):
    """
    Predict the next upcoming F1 race.
    """
    print("\n" + "=" * 70)
    print("[F1] FINDING NEXT RACE...")
    print("=" * 70)

    race_info = get_next_race_info(year)

    if race_info is None:
        print("Could not find upcoming race information.")
        return None

    print(f"Next Race: {race_info['event_name']}")
    print(f"Date: {race_info['event_date'].strftime('%Y-%m-%d')}")
    print(f"Round: {race_info['round']}")
    print(f"Qualifying Data Available: {'Yes' if race_info['qualifying_available'] else 'No'}")
    print("-" * 70)

    results = None
    if mode == "standings":
        print("\nUsing standings-based mode (pre-qualifying strategy).")
        print("-" * 70)
        results = build_prediction_from_standings(race_info['year'], model_name)
        if not results.empty:
            display_predictions(results, f"{race_info['event_name']} (Pre-Qualifying)")
            return results
        print("Could not generate standings-based prediction.")
        return None

    if mode == "qualifying":
        if not race_info['qualifying_available']:
            print("\nQualifying has not happened yet for this race.")
            print("Run with '--next-mode standings' to predict using pre-qualifying data.")
            return None
        print("\nUsing qualifying-based mode (post-qualifying strategy).")
        print("-" * 70)
        results = predict_race(
            race_info['year'],
            race_info['round'],
            model_name,
            data_prefix
        )
    else:
        if race_info['qualifying_available']:
            print("\nQualifying appears available. Using qualifying-based prediction.")
            print("-" * 70)
            results = predict_race(
                race_info['year'],
                race_info['round'],
                model_name,
                data_prefix
            )
        else:
            print("\nQualifying hasn't happened yet.")
            print("Using standings-based pre-qualifying prediction.")
            print("-" * 70)
            results = build_prediction_from_standings(race_info['year'], model_name)
            if not results.empty:
                display_predictions(results, f"{race_info['event_name']} (Pre-Qualifying)")
                return results

    if not results.empty:
        display_predictions(results, f"{race_info['event_name']} (Post-Qualifying)")
        return results
    else:
        print("Could not generate predictions with the selected mode.")
        return None


def predict_with_custom_grid(grid_order: list, year: int = 2025, model_name: str = "best_model"):
    """
    Make predictions with a custom starting grid.
    Useful for predicting before qualifying or with hypothetical scenarios.

    Args:
        grid_order: List of driver abbreviations in grid order (P1 first)
        year: Season year for standings data
        model_name: Model to use
    """
    model = load_model(model_name)
    standings = get_current_standings(year)

    if standings.empty:
        # Use previous year's final standings
        standings = get_current_standings(year - 1)

    features = []
    for grid_pos, driver in enumerate(grid_order, 1):
        driver_standing = standings[standings['Driver'] == driver]

        if len(driver_standing) > 0:
            driver_champ_pos = driver_standing['DriverChampionshipPosition'].values[0]
            driver_points = driver_standing['DriverPointsBefore'].values[0]
            team = driver_standing['TeamName'].values[0]
            constructor_champ_pos = driver_standing['ConstructorChampionshipPosition'].values[0]
            constructor_points = driver_standing['ConstructorPointsBefore'].values[0]
        else:
            driver_champ_pos = 20
            driver_points = 0
            team = "Unknown"
            constructor_champ_pos = 10
            constructor_points = 0

        features.append({
            'Driver': driver,
            'FullName': driver,
            'Team': team,
            'GridPosition': grid_pos,
            'DriverChampPosition': driver_champ_pos,
            'DriverPoints': driver_points,
            'ConstructorChampPosition': constructor_champ_pos,
            'ConstructorPoints': constructor_points,
            'TrackHistoryAvgPos': grid_pos,
            'RecentForm': grid_pos,
            'QualifyingGap': 5.0
        })

    features_df = pd.DataFrame(features)
    feature_cols = get_feature_columns()
    X = features_df[feature_cols]

    predictions = predict_positions(model, X)

    results = features_df[['Driver', 'FullName', 'Team', 'GridPosition']].copy()
    results['PredictedPosition'] = predictions
    results = results.sort_values('PredictedPosition').reset_index(drop=True)
    results['PredictedRank'] = range(1, len(results) + 1)

    return results


def predict_from_standings(year: int = None, model_name: str = "best_model"):
    """
    Predict race using championship standings as estimated grid order.
    Use this when qualifying data is not available yet.
    """
    print("\n" + "=" * 70)
    print("[F1] PREDICTION FROM CHAMPIONSHIP STANDINGS")
    print("=" * 70)
    print("Note: Using championship order as estimated grid")
    print("      (Qualifying data not available)")
    print("-" * 70)

    if year is None:
        year = pd.Timestamp.now().year

    results = build_prediction_from_standings(year, model_name)
    if results.empty:
        print("Could not load standings data.")
        return None

    display_predictions(results, f"{year} Championship-Based Prediction")

    return results


